# Construct the solution using two copies of affine plane of order 5

NUM_GOLFERS = 50
NUM_GROUPS = 10
GROUP_SIZE = 5
NUM_WEEKS = 6

# First, build the affine plane of order 5 for 25 points
def affine_plane_order_5():
    """Return 6 parallel classes for 25 points, each class is a list of 5 groups of 5"""
    point_to_idx = {(x, y): x * 5 + y for x in range(5) for y in range(5)}

    weeks = []

    # Vertical lines: x = c
    week = []
    for c in range(5):
        group = [point_to_idx[(c, y)] for y in range(5)]
        week.append(group)
    weeks.append(week)

    # Lines with slope m: y = mx + b (mod 5)
    for m in range(5):
        week = []
        for b in range(5):
            group = [point_to_idx[(x, (m*x + b) % 5)] for x in range(5)]
            week.append(group)
        weeks.append(week)

    return weeks

weeks_25 = affine_plane_order_5()

# Now build the 50-golfer schedule
# Copy A: golfers 0-24, Copy B: golfers 25-49
schedule = [[0] * NUM_GOLFERS for _ in range(NUM_WEEKS)]

for w in range(NUM_WEEKS):
    # Copy A: groups 0-4
    for g_idx, group in enumerate(weeks_25[w]):
        for p in group:
            schedule[w][p] = g_idx  # group 0-4

    # Copy B: groups 5-9
    for g_idx, group in enumerate(weeks_25[w]):
        for p in group:
            schedule[w][p + 25] = g_idx + 5  # group 5-9

# Verify
def verify(schedule):
    pair_weeks = {}
    for w in range(NUM_WEEKS):
        for g in range(NUM_GROUPS):
            golfers = [p for p in range(NUM_GOLFERS) if schedule[w][p] == g]
            if len(golfers) != GROUP_SIZE:
                print(f"Week {w}, group {g}: expected {GROUP_SIZE} golfers, got {len(golfers)}: {golfers}")
                return False
            for i in range(len(golfers)):
                for j in range(i+1, len(golfers)):
                    a, b = golfers[i], golfers[j]
                    if a > b:
                        a, b = b, a
                    if (a,b) in pair_weeks:
                        print(f"Pair ({a},{b}) appears in weeks {pair_weeks[(a,b)]} and {w}")
                        return False
                    pair_weeks[(a,b)] = w
    print(f"Verification passed! {len(pair_weeks)} unique pairs used.")
    return True

verify(schedule)

